import axios from 'axios';
import { ShopHistoryListRequestDTO, ShopListResponseDTO } from '~/entities/shop/dtos/shop-list';
import { Place } from '~/entities/shop/dtos/types';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

export const shopApi = {
  getShopList: (placeId?: string | void) => resultify(axios.post<Place[]>(API_URLS.voucherPlaceReadList, { placeId })),
  getPlaceReadListByRadius: (placeSearchParam: ShopHistoryListRequestDTO) =>
    resultify(axios.post<ShopListResponseDTO>(API_URLS.voucherPlaceReadListByRadius, { ...placeSearchParam })),
} as const;
